#!/usr/bin/env bun

import { z } from "zod"
import { Config } from "../packages/nikcli/src/config/config"

const file = process.argv[2]
console.log(file)

const result = z.toJSONSchema(Config.Info, {
  io: "input", // Generate input shape (treats optional().default() as not required)
  /**
   * We'll use the `default` values of the field as the only value in `examples`.
   * This will ensure no docs are needed to be read, as the configuration is
   * self-documenting.
   *
   * See https://json-schema.org/draft/2020-12/draft-bhutton-json-schema-validation-00#rfc.section.9.5
   */
  override(ctx) {
    const schema = ctx.jsonSchema

    // Preserve strictness: set additionalProperties: false for objects
    if (schema && typeof schema === "object" && schema.type === "object" && schema.additionalProperties === undefined) {
      schema.additionalProperties = false
    }

    // Add examples and default descriptions for string fields with defaults
    if (schema && typeof schema === "object" && "type" in schema && schema.type === "string" && schema?.default) {
      if (!schema.examples) {
        schema.examples = [schema.default]
      }

      schema.description = [schema.description || "", `default: \`${schema.default}\``]
        .filter(Boolean)
        .join("\n\n")
        .trim()
    }
  },
}) as Record<string, unknown> & {
  allowComments?: boolean
  allowTrailingCommas?: boolean
}

// used for json lsps since config supports jsonc
result.allowComments = true
result.allowTrailingCommas = true

if (!file) {
  throw new Error("No output file provided.")
}

await Bun.write(file as string, JSON.stringify(result, null, 2))

import type { MiddlewareHandler } from "hono"
import { createRemoteJWKSet, jwtVerify } from "jose"
import type { JWTPayload } from "jose"
import { ensureUser } from "./db"
import type { AuthContext, CloudBindings, CloudEnv } from "./types"

const jwksCache = new Map<string, ReturnType<typeof createRemoteJWKSet>>()

function getRemoteJwks(url: string): ReturnType<typeof createRemoteJWKSet> {
  const cached = jwksCache.get(url)
  if (cached) return cached

  const created = createRemoteJWKSet(new URL(url))
  jwksCache.set(url, created)
  return created
}

function parseBearerToken(value?: string | null): string | null {
  if (!value) return null
  const [kind, token] = value.split(" ")
  if (kind?.toLowerCase() !== "bearer") return null
  if (!token) return null
  return token
}

export async function verifyAuthToken(token: string, env: CloudBindings): Promise<AuthContext> {
  const issuer = env.AUTH_ISSUER
  const audience = env.AUTH_AUDIENCE

  let payload: JWTPayload
  if (env.AUTH_JWKS_URL) {
    const jwks = getRemoteJwks(env.AUTH_JWKS_URL)
    const verified = await jwtVerify(token, jwks, {
      algorithms: ["RS256", "RS384", "RS512", "ES256", "ES384", "ES512", "EdDSA"],
      ...(issuer ? { issuer } : {}),
      ...(audience ? { audience } : {}),
    })
    payload = verified.payload
  } else if (env.AUTH_JWT_SECRET) {
    const secret = new TextEncoder().encode(env.AUTH_JWT_SECRET)
    const verified = await jwtVerify(token, secret, {
      algorithms: ["HS256", "HS384", "HS512"],
      ...(issuer ? { issuer } : {}),
      ...(audience ? { audience } : {}),
    })
    payload = verified.payload
  } else {
    throw new Error("Missing auth verifier configuration")
  }

  const userID = typeof payload.sub === "string" ? payload.sub : ""
  if (!userID) {
    throw new Error("Missing subject claim in auth token")
  }

  return {
    userID,
    email: typeof payload.email === "string" ? payload.email : undefined,
    token,
    claims: payload,
  }
}

export async function authenticateRequest(
  request: Request,
  env: CloudBindings,
  options?: { allowQueryToken?: boolean },
): Promise<AuthContext> {
  const requestURL = new URL(request.url)
  const queryToken = options?.allowQueryToken ? requestURL.searchParams.get("token") : null
  const authToken = parseBearerToken(request.headers.get("authorization"))
  const token = authToken ?? queryToken

  if (!token) {
    throw new Error("Missing bearer token")
  }

  return verifyAuthToken(token, env)
}

export const requireAuth: MiddlewareHandler<CloudEnv> = async (c, next) => {
  try {
    const auth = await authenticateRequest(c.req.raw, c.env, { allowQueryToken: false })
    await ensureUser(c.env.DB, auth)
    c.set("auth", auth)
    await next()
  } catch {
    return c.json(
      {
        error: {
          code: "UNAUTHORIZED",
          message: "Invalid or missing authentication token",
        },
      },
      401,
    )
  }
}

import type { AuthContext, DeviceRecord, MessageRecord, SessionRecord, SyncOperationRecord } from "./types"
import type { DeviceRegistrationInput, MessageCreateInput, SessionUpsertInput, SyncOperationInput } from "./schema"

function asNumber(value: unknown): number {
  if (typeof value === "number") return value
  if (typeof value === "string") {
    const parsed = Number(value)
    return Number.isFinite(parsed) ? parsed : 0
  }
  return 0
}

function asString(value: unknown): string {
  return typeof value === "string" ? value : ""
}

function mapSessionRow(row: Record<string, unknown>): SessionRecord {
  return {
    id: asString(row.id),
    userID: asString(row.user_id),
    title: asString(row.title),
    directoryHash: asString(row.directory_hash) || undefined,
    encryptedState: asString(row.encrypted_state),
    syncVersion: asNumber(row.sync_version),
    createdAt: asNumber(row.created_at),
    updatedAt: asNumber(row.updated_at),
  }
}

function mapMessageRow(row: Record<string, unknown>): MessageRecord {
  return {
    id: asString(row.id),
    sessionID: asString(row.session_id),
    userID: asString(row.user_id),
    deviceID: asString(row.device_id) || undefined,
    role: asString(row.role),
    encryptedContent: asString(row.encrypted_content),
    createdAt: asNumber(row.created_at),
    syncVersion: asNumber(row.sync_version),
  }
}

function mapSyncRow(row: Record<string, unknown>): SyncOperationRecord {
  return {
    id: asNumber(row.id),
    userID: asString(row.user_id),
    sessionID: asString(row.session_id),
    deviceID: asString(row.device_id) || undefined,
    operation: asString(row.operation) as SyncOperationRecord["operation"],
    entityType: asString(row.entity_type) as SyncOperationRecord["entityType"],
    entityID: asString(row.entity_id),
    payload: asString(row.payload) || undefined,
    hash: asString(row.hash),
    createdAt: asNumber(row.created_at),
  }
}

function mapDeviceRow(row: Record<string, unknown>): DeviceRecord {
  return {
    id: asString(row.id),
    userID: asString(row.user_id),
    name: asString(row.name),
    platform: asString(row.platform) as DeviceRecord["platform"],
    publicKey: asString(row.public_key),
    pushToken: asString(row.push_token) || undefined,
    createdAt: asNumber(row.created_at),
    lastSeen: asNumber(row.last_seen),
  }
}

export async function ensureUser(db: D1Database, auth: AuthContext): Promise<void> {
  const now = Date.now()
  await db
    .prepare(
      `INSERT INTO users (id, email, created_at, last_login)
       VALUES (?1, ?2, ?3, ?3)
       ON CONFLICT(id) DO UPDATE SET
         email = excluded.email,
         last_login = excluded.last_login`,
    )
    .bind(auth.userID, auth.email ?? null, now)
    .run()
}

export async function registerDevice(
  db: D1Database,
  auth: AuthContext,
  input: DeviceRegistrationInput,
): Promise<DeviceRecord> {
  const now = Date.now()

  const existing = await db
    .prepare(`SELECT user_id FROM devices WHERE id = ?1 LIMIT 1`)
    .bind(input.deviceID)
    .first<{ user_id: string }>()

  if (existing && existing.user_id !== auth.userID) {
    throw new Error("device_conflict")
  }

  await db
    .prepare(
      `INSERT INTO devices (
          id,
          user_id,
          name,
          platform,
          public_key,
          push_token,
          created_at,
          last_seen
        ) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?7)
        ON CONFLICT(id) DO UPDATE SET
          name = excluded.name,
          platform = excluded.platform,
          public_key = excluded.public_key,
          push_token = excluded.push_token,
          last_seen = excluded.last_seen
        WHERE devices.user_id = excluded.user_id`,
    )
    .bind(input.deviceID, auth.userID, input.name, input.platform, input.publicKey, input.pushToken ?? null, now)
    .run()

  return {
    id: input.deviceID,
    userID: auth.userID,
    name: input.name,
    platform: input.platform,
    publicKey: input.publicKey,
    pushToken: input.pushToken,
    createdAt: now,
    lastSeen: now,
  }
}

export async function listDevices(db: D1Database, userID: string): Promise<DeviceRecord[]> {
  const result = await db
    .prepare(
      `SELECT id, user_id, name, platform, public_key, push_token, created_at, last_seen
       FROM devices
       WHERE user_id = ?1
       ORDER BY last_seen DESC`,
    )
    .bind(userID)
    .all<Record<string, unknown>>()

  return (result.results ?? []).map(mapDeviceRow)
}

export async function deviceBelongsToUser(db: D1Database, userID: string, deviceID: string): Promise<boolean> {
  const result = await db
    .prepare(`SELECT 1 AS found FROM devices WHERE id = ?1 AND user_id = ?2 LIMIT 1`)
    .bind(deviceID, userID)
    .first<{ found: number }>()

  return result?.found === 1
}

export async function sessionBelongsToUser(db: D1Database, userID: string, sessionID: string): Promise<boolean> {
  const result = await db
    .prepare(`SELECT 1 AS found FROM sessions WHERE id = ?1 AND user_id = ?2 LIMIT 1`)
    .bind(sessionID, userID)
    .first<{ found: number }>()

  return result?.found === 1
}

export async function getSession(db: D1Database, userID: string, sessionID: string): Promise<SessionRecord | null> {
  const row = await db
    .prepare(
      `SELECT id, user_id, title, directory_hash, encrypted_state, sync_version, created_at, updated_at
       FROM sessions
       WHERE id = ?1 AND user_id = ?2
       LIMIT 1`,
    )
    .bind(sessionID, userID)
    .first<Record<string, unknown>>()

  if (!row) return null
  return mapSessionRow(row)
}

export async function listSessions(db: D1Database, userID: string, limit = 50): Promise<SessionRecord[]> {
  const result = await db
    .prepare(
      `SELECT id, user_id, title, directory_hash, encrypted_state, sync_version, created_at, updated_at
       FROM sessions
       WHERE user_id = ?1
       ORDER BY updated_at DESC
       LIMIT ?2`,
    )
    .bind(userID, limit)
    .all<Record<string, unknown>>()

  return (result.results ?? []).map(mapSessionRow)
}

