async function getUserPrompt() {
  const context = useContext()
  const payload = context.payload as IssueCommentEvent | PullRequestReviewCommentEvent
  const reviewContext = getReviewCommentContext()

  let prompt = (() => {
    const body = payload.comment.body.trim()
    if (body === "/nikcli" || body === "/oc") {
      if (reviewContext) {
        return `Review this code change and suggest improvements for the commented lines:\n\nFile: ${reviewContext.file}\nLines: ${reviewContext.line}\n\n${reviewContext.diffHunk}`
      }
      return "Summarize this thread"
    }
    if (body.includes("/nikcli") || body.includes("/oc")) {
      if (reviewContext) {
        return `${body}\n\nContext: You are reviewing a comment on file "${reviewContext.file}" at line ${reviewContext.line}.\n\nDiff context:\n${reviewContext.diffHunk}`
      }
      return body
    }
    throw new Error("Comments must mention `/nikcli` or `/oc`")
  })()

  // Handle images
  const imgData: {
    filename: string
    mime: string
    content: string
    start: number
    end: number
    replacement: string
  }[] = []

  // Search for files
  // ie. <img alt="Image" src="https://github.com/user-attachments/assets/xxxx" />
  // ie. [api.json](https://github.com/user-attachments/files/21433810/api.json)
  // ie. ![Image](https://github.com/user-attachments/assets/xxxx)
  const mdMatches = prompt.matchAll(/!?\[.*?\]\((https:\/\/github\.com\/user-attachments\/[^)]+)\)/gi)
  const tagMatches = prompt.matchAll(/<img .*?src="(https:\/\/github\.com\/user-attachments\/[^"]+)" \/>/gi)
  const matches = [...mdMatches, ...tagMatches].sort((a, b) => a.index - b.index)
  console.log("Images", JSON.stringify(matches, null, 2))

  let offset = 0
  for (const m of matches) {
    const tag = m[0]
    const url = m[1]
    const start = m.index

    if (!url) continue
    const filename = path.basename(url)

    // Download image
    const res = await fetch(url, {
      headers: {
        Authorization: `Bearer ${accessToken}`,
        Accept: "application/vnd.github.v3+json",
      },
    })
    if (!res.ok) {
      console.error(`Failed to download image: ${url}`)
      continue
    }

    // Replace img tag with file path, ie. @image.png
    const replacement = `@${filename}`
    prompt = prompt.slice(0, start + offset) + replacement + prompt.slice(start + offset + tag.length)
    offset += replacement.length - tag.length

    const contentType = res.headers.get("content-type")
    imgData.push({
      filename,
      mime: contentType?.startsWith("image/") ? contentType : "text/plain",
      content: Buffer.from(await res.arrayBuffer()).toString("base64"),
      start,
      end: start + replacement.length,
      replacement,
    })
  }
  return { userPrompt: prompt, promptFiles: imgData }
}

async function subscribeSessionEvents() {
  console.log("Subscribing to session events...")

  const TOOL: Record<string, [string, string]> = {
    todowrite: ["Todo", "\x1b[33m\x1b[1m"],
    todoread: ["Todo", "\x1b[33m\x1b[1m"],
    bash: ["Bash", "\x1b[31m\x1b[1m"],
    edit: ["Edit", "\x1b[32m\x1b[1m"],
    glob: ["Glob", "\x1b[34m\x1b[1m"],
    grep: ["Grep", "\x1b[34m\x1b[1m"],
    list: ["List", "\x1b[34m\x1b[1m"],
    read: ["Read", "\x1b[35m\x1b[1m"],
    write: ["Write", "\x1b[32m\x1b[1m"],
    websearch: ["Search", "\x1b[2m\x1b[1m"],
  }

  const response = await fetch(`${server.url}/event`)
  if (!response.body) throw new Error("No response body")

  const reader = response.body.getReader()
  const decoder = new TextDecoder()

  let text = ""
    ; (async () => {
      while (true) {
        try {
          const { done, value } = await reader.read()
          if (done) break

          const chunk = decoder.decode(value, { stream: true })
          const lines = chunk.split("\n")

          for (const line of lines) {
            if (!line.startsWith("data: ")) continue

            const jsonStr = line.slice(6).trim()
            if (!jsonStr) continue

            try {
              const evt = JSON.parse(jsonStr)

              if (evt.type === "message.part.updated") {
                if (evt.properties.part.sessionID !== session.id) continue
                const part = evt.properties.part

                if (part.type === "tool" && part.state.status === "completed") {
                  const [tool, color] = TOOL[part.tool] ?? [part.tool, "\x1b[34m\x1b[1m"]
                  const title =
                    part.state.title || Object.keys(part.state.input).length > 0
                      ? JSON.stringify(part.state.input)
                      : "Unknown"
                  console.log()
                  console.log(color + `|`, "\x1b[0m\x1b[2m" + ` ${tool.padEnd(7, " ")}`, "", "\x1b[0m" + title)
                }

                if (part.type === "text") {
                  text = part.text

                  if (part.time?.end) {
                    console.log()
                    console.log(text)
                    console.log()
                    text = ""
                  }
                }
              }

              if (evt.type === "session.updated") {
                if (evt.properties.info.id !== session.id) continue
                session = evt.properties.info
              }
            } catch (e) {
              // Ignore parse errors
            }
          }
        } catch (e) {
          console.log("Subscribing to session events done", e)
          break
        }
      }
    })()
}

async function summarize(response: string) {
  try {
    return await chat(`Summarize the following in less than 40 characters:\n\n${response}`)
  } catch (e) {
    if (isScheduleEvent()) {
      return "Scheduled task changes"
    }
    const payload = useContext().payload as IssueCommentEvent
    return `Fix issue: ${payload.issue.title}`
  }
}

async function resolveAgent(): Promise<string | undefined> {
  const envAgent = useEnvAgent()
  if (!envAgent) return undefined

  // Validate the agent exists and is a primary agent
  const agents = await client.app.agents<true>()
  const agent = agents.data.find((a) => a.name === envAgent)

  if (!agent) {

    console.warn(`agent "${envAgent}" not found. Falling back to default agent`)
    return undefined
  }

  if (agent.mode === "subagent") {
    console.warn(`agent "${envAgent}" is a subagent, not a primary agent. Falling back to default agent`)
    return undefined
  }

  return envAgent
}

async function chat(text: string, files: PromptFiles = []) {
  console.log("Sending message to nikcli...")
  const { providerID, modelID } = useEnvModel()
  const agent = await resolveAgent()

  const chat = await client.session.prompt<true>({
    path: session,
    body: {
      model: {
        providerID,
        modelID,
      },
      agent,
      parts: [
        {
          type: "text",
          text,
        },
        ...files.flatMap((f) => [
          {
            type: "file" as const,
            mime: f.mime,
            url: `data:${f.mime};base64,${f.content}`,
            filename: f.filename,
            source: {
              type: "file" as const,
              text: {
                value: f.replacement,
                start: f.start,
                end: f.end,
              },
              path: f.filename,
            },
          },
        ]),
      ],
    },
  })

  // @ts-ignore
  const match = chat.data.parts.findLast((p) => p.type === "text")
  if (!match) throw new Error("Failed to parse the text response")

  return match.text
}

async function configureGit(appToken: string) {
  // Do not change git config when running locally
  if (isMock()) return

  console.log("Configuring git...")
  const config = "http.https://github.com/.extraheader"
  const ret = await $`git config --local --get ${config}`
  gitConfig = ret.stdout.toString().trim()

  const newCredentials = Buffer.from(`x-access-token:${appToken}`, "utf8").toString("base64")

  await $`git config --local --unset-all ${config}`
  await $`git config --local ${config} "AUTHORIZATION: basic ${newCredentials}"`
  await $`git config --global user.name "nikcli-agent[bot]"`
  await $`git config --global user.email "nikcli-agent[bot]@users.noreply.github.com"`
}

async function restoreGitConfig() {
  if (gitConfig === undefined) return
  console.log("Restoring git config...")
  const config = "http.https://github.com/.extraheader"
  await $`git config --local ${config} "${gitConfig}"`
}

async function checkoutNewBranch() {
  console.log("Checking out new branch...")
  const branch = generateBranchName("issue")
  await $`git checkout -b ${branch}`
  return branch
}

async function checkoutLocalBranch(pr: GitHubPullRequest) {
  console.log("Checking out local branch...")

  const branch = pr.headRefName
  const depth = Math.max(pr.commits.totalCount, 20)

  await $`git fetch origin --depth=${depth} ${branch}`
  await $`git checkout ${branch}`
}

async function checkoutForkBranch(pr: GitHubPullRequest) {
  console.log("Checking out fork branch...")

  const remoteBranch = pr.headRefName
  const localBranch = generateBranchName("pr")
  const depth = Math.max(pr.commits.totalCount, 20)

  await $`git remote add fork https://github.com/${pr.headRepository.nameWithOwner}.git`
  await $`git fetch fork --depth=${depth} ${remoteBranch}`
  await $`git checkout -b ${localBranch} fork/${remoteBranch}`
}

function generateBranchName(type: "issue" | "pr") {
  const timestamp = new Date()
    .toISOString()
    .replace(/[:-]/g, "")
    .replace(/\.\d{3}Z/, "")
    .split("T")
    .join("")
  return `nikcli/${type}${useIssueId()}-${timestamp}`
}

